// Candidate-only integration gate; executes the actual delivered/shared flight WASM.
import fs from 'node:fs';
import vm from 'node:vm';
import test from 'node:test';
import assert from 'node:assert/strict';
import {performance} from 'node:perf_hooks';
const helper=new URL('../tools/frontline_local_flight.js',import.meta.url);
const context=vm.createContext({console,Float32Array,Uint8Array,Map,Math,Number,Object,Array});
if(fs.existsSync(helper))vm.runInContext(fs.readFileSync(helper,'utf8'),context);
const module=await WebAssembly.compile(fs.readFileSync(process.env.TF_LOCAL_FLIGHT_WASM||'handoff/flight/flight_core.wasm'));
const physics=JSON.parse(fs.readFileSync('data/aircraft/frontline.json')).aircraft.me262.physics;
async function core(){return(await WebAssembly.instantiate(module,{math:{sin:Math.sin,cos:Math.cos,atan2:Math.atan2,exp:Math.exp,asin:Math.asin,acos:Math.acos},world:{ground:()=>0,landable:()=>1}})).exports;}
function configure(api,unit){api.set_world(1);api.configure_airframe(...unit.flight.airframe);api.configure_surfaces(...physics.surfaces);api.configure_gear_sequence(...physics.gearSequence);api.configure(...physics.configure);api.configure_control(...physics.control);api.configure_envelope(...physics.envelope);}
async function fixture(prepare=()=>{}){
 assert.equal(typeof context.createFrontlineLocalFlight,'function','local owner must run the real original flight plant');
 const initial=await core();const unit={unit:{battle:11,unit:7,life:1},epoch:3,aircraft:'me262',alive:true,resource_revision:1,flight:{airframe:physics.airframe.slice(),factors:[1,1,1,1,1,1]},airframe_limits:{gear_failed:false},guns:[{ammo:42}],fuel:{kg:500,max:500},stores:[],damage:{revision:1}};
 configure(initial,unit);initial.spawn(0,2000,0,0,160,0);unit.state=Array.from(new Float32Array(initial.memory.buffer,initial.state_ptr(),80));unit.aero=Array.from(new Float32Array(initial.memory.buffer,initial.aero_state_ptr(),48));
 prepare(unit);
 const plane={api:{},S:Float32Array.from(unit.state),aero:Float32Array.from(unit.aero),cur:Float32Array.from(unit.state),prev:Float32Array.from(unit.state),pose(alpha){this.lastAlpha=alpha;},damage:{step(){throw Error('local damage forbidden');}}};
 const api=await core(),owner=context.createFrontlineLocalFlight({api,plane,unit,epoch:3,configure});return{unit,plane,api,owner};
}
const intent={aim:[0,0,1],throttle:1,manual_pitch:.6,manual_roll:0,manual_yaw:0,flags:1};
test('owned aircraft advances original plant and surface animation before any network reply',async()=>{const x=await fixture(),before=JSON.stringify(x.unit);const z=x.plane.cur[2];x.owner.step(1/60,intent);assert.ok(x.plane.cur[2]>z);assert.ok(x.plane.cur[24]>0);assert.ok(x.plane.lastAlpha>=0&&x.plane.lastAlpha<=1);assert.equal(JSON.stringify(x.unit),before);assert.equal(x.plane.api,x.api);});
test('initial handoff preserves an accepted running engine and partial original gear mechanism',async()=>{const x=await fixture(u=>{u.state[27]=.91;u.state[24]=.2;u.state[33]=.6;u.state[34]=.25;u.aero[23]=.5;u.aero[36]=1;u.aero[37]=1;u.aero[38]=.2;u.aero[39]=1;});assert.ok(Math.abs(x.plane.cur[27]-.91)<1e-6);assert.ok(Math.abs(x.plane.cur[33]-.6)<1e-6);assert.ok(Math.abs(x.plane.aero[38]-.2)<1e-6);x.owner.step(1/120,{...intent,flags:133});assert.ok(x.plane.cur[33]>.6&&x.plane.cur[33]<.61);});
test('pose packets contain only scoped movement and acknowledgements cannot cross lives',async()=>{const x=await fixture();x.owner.step(.05,intent);const packet=x.owner.packet(9);assert.equal(packet.epoch,3);assert.equal(packet.unit.life,1);assert.equal(packet.pose.position.length,3);assert.equal(packet.pose.quaternion.length,4);assert.deepEqual(Object.keys(packet).sort(),['epoch','pose','seq','unit']);assert.equal(x.owner.ack({...packet,unit:{...packet.unit,life:2}}),false);assert.equal(x.owner.ack(packet),true);assert.equal(x.owner.ack(packet),false);});
test('accepted damage and irreversible gear failure affect local forces without spending native resources',async()=>{const x=await fixture(),damaged=structuredClone(x.unit);damaged.resource_revision=2;damaged.damage.revision=2;damaged.state[23]=.2;damaged.flight.factors=[0,1,1,.5,.6,.7];damaged.airframe_limits.gear_failed=true;const resources=JSON.stringify([damaged.guns,damaged.fuel,damaged.stores]);assert.equal(x.owner.accept(damaged,3),true);x.owner.step(.1,{...intent,flags:133});assert.equal(x.plane.cur[37],0);assert.equal(x.plane.cur[33],0);assert.equal(x.owner.accept(x.unit,3),false,'old accepted sample cannot repair new damage');assert.equal(JSON.stringify([damaged.guns,damaged.fuel,damaged.stores]),resources);});
test('explicit server correction is bounded and an epoch change stops local movement',async()=>{const x=await fixture();x.owner.step(.05,intent);const corrected=structuredClone(x.unit);corrected.state[0]=20;corrected.state[23]=.05;x.owner.correct(corrected);const before=x.plane.cur[0];x.owner.step(1/60,intent);assert.ok(x.plane.cur[0]>before&&x.plane.cur[0]<20);const p=x.plane.cur[2];assert.equal(x.owner.accept({...x.unit,epoch:4},4),false);x.owner.step(.1,intent);assert.equal(x.plane.cur[2],p);});
test('pose rejection waits for a fresh native snapshot and reseeds clock without a permanent retry loop',async()=>{const x=await fixture();x.owner.step(.1,intent);x.owner.packet(1);assert.equal(typeof x.owner.reject,'function');x.owner.reject();assert.equal(x.owner.packet(2),null);const fresh=structuredClone(x.unit);fresh.state[23]=2;fresh.state[2]=320;x.owner.accept(fresh,3);x.owner.step(1/60,intent);const packet=x.owner.packet(3);assert.ok(packet.pose.sample_time_s>=2);assert.ok(packet.pose.position[2]>300,'physical plant must rebase immediately; render correction may remain smooth');});
test('the first accepted service completion can repair a locally latched gear failure',async()=>{const x=await fixture(),failed=structuredClone(x.unit);failed.state[23]=.1;failed.resource_revision=2;failed.airframe_limits.gear_failed=true;x.owner.accept(failed,3);x.owner.step(.05,{...intent,flags:133});assert.equal(x.plane.cur[33],0);const repaired=structuredClone(x.unit);repaired.state[1]=2;repaired.state[35]=2;repaired.state[36]=4;repaired.state[33]=1;for(const slot of [36,37,38,39])repaired.aero[slot]=1;repaired.state[23]=.3;repaired.resource_revision=3;repaired.service={status:'complete',revision:1};repaired.service_revision=1;x.owner.accept(repaired,3);x.owner.step(1/60,{...intent,flags:133});assert.ok(x.plane.cur[33]>.99);});
test('observer snapshots interpolate position and mechanism surfaces without a flight step',()=>{assert.equal(typeof context.createFrontlineFlightInterpolation,'function');const plane={cur:new Float32Array(80),prev:new Float32Array(80),S:new Float32Array(80),aero:new Float32Array(48),pose(){},api:{step(){throw Error('observer plant forbidden');}}};const s=new Float32Array(80),a=new Float32Array(48);s[6]=1;s[1]=100;s[23]=1;const buffer=context.createFrontlineFlightInterpolation(plane);buffer.accept(s,a);const next=s.slice(),axes=a.slice();next[0]=10;next[23]=1.05;next[24]=1;axes[36]=1;buffer.accept(next,axes);buffer.pose(.025);assert.ok(Math.abs(plane.cur[0]-5)<.001);assert.ok(Math.abs(plane.cur[24]-.5)<.001);assert.ok(Math.abs(plane.aero[36]-.5)<.001);});

async function actualModel(createCore=core){
 const source=fs.readFileSync('handoff/bundle/app.js.html','utf8'),a=source.indexOf('  // the C flight core'),b=source.indexOf('  // client/web/src/main.js',a),c=vm.createContext({performance,atob});
 vm.runInContext(source.slice(source.indexOf('  function m4()'),source.indexOf('  // client/web/src/game/relief.js'))+source.slice(source.lastIndexOf('\n',a)+1,b)+fs.readFileSync('handoff/tools/frontline_contact_visual.js','utf8')+fs.readFileSync(helper,'utf8')+fs.readFileSync('handoff/tools/frontline_aircraft_visual.js','utf8'),c);
 const renderer={mesh:data=>({count:data.length/13,_src:{data}}),freeMesh(){}};
 const model=c.createFrontlineAircraftVisual(renderer,'me262',{createFlightCore:createCore,configureFlight:configure,interpolate:true});
 const {unit}=await fixture();unit.damage={...unit.damage,parts:model.plane.damage.parts.map(p=>[p.max,0]),fire:false,broken:false};
 model.accept(unit,1);model.setControlled(true,new Set());return{c,model,unit};
}
test('actual Aircraft adapter binds the real kernel, animates without an echo, and ignores ordinary stale poses',async()=>{const x=await actualModel();assert.equal(typeof x.model.localStep,'function','the actual online adapter must expose local flight stepping');await x.model.localReady;const z=x.model.plane.cur[2],stock=JSON.stringify(x.unit);x.model.localStep(1/60,intent);x.model.pose(1/60);x.model.root.update();assert.ok(x.model.plane.cur[2]>z);assert.ok(x.model.plane.cur[24]>0);const advanced=x.model.plane.cur[2];x.model.accept({...x.unit},2);assert.equal(x.model.plane.cur[2],advanced,'a normal accepted resource frame must not rewind owned motion');assert.equal(JSON.stringify(x.unit),stock);x.model.setControlled(false);assert.throws(()=>x.model.plane.api.step(),/cannot step flight/);x.model.dispose();});
test('late async kernel creation cannot rebind a released or replaced control epoch',async()=>{let ready;const delayed=new Promise(resolve=>ready=resolve),x=await actualModel(()=>delayed);x.model.setControlled(false);ready(await core());await x.model.localReady;assert.throws(()=>x.model.plane.api.step(),/cannot step flight/);x.model.dispose();});
test('the local world admits only mapped intact runway patches',()=>{assert.equal(typeof context.createFrontlineFlightWorld,'function');const f={room:{facility_layout_version:1},map:{terrain:{x0:-100,z0:-100,width:3,height:3,cellX:100,cellZ:100},airfields:[{id:'field',enabled:true,runway:{center:[0,0],forward:[0,1],lengthMeters:100,widthMeters:20}}]},facilities:[{facility_id:'a',kind:'runway_patch',source_id:'field',capabilities:{landable:true}},{facility_id:'b',kind:'runway_patch',source_id:'field',capabilities:{landable:false}}],facilityCatalog:[{facility_id:'a',source:{longitudinalMeters:[-50,0]}},{facility_id:'b',source:{longitudinalMeters:[0,50]}}]};const world=context.createFrontlineFlightWorld(f,()=>5);assert.equal(world.ground(0,0),5);assert.equal(world.landable(0,-25),true);assert.equal(world.landable(0,25),false);assert.equal(world.landable(11,-25),false);assert.equal(world.landable(0,-101),false);});
test('the actual native heartbeat sends scoped local pose after input with one monotonic sequence',async()=>{const x=await fixture();x.owner.step(.05,intent);const runtime=fs.readFileSync('handoff/tools/frontline_existing_runtime.js','utf8'),from=runtime.indexOf('  function transmit(){'),to=runtime.indexOf('  function clear(){',from),messages=[],selection={store_id:null,store_index:null,program:'single',gun_mode:'all'};x.unit.weapon_control=selection;const air={};const c=vm.createContext({f:{epoch:3,seq:0},bridge:{getair:()=>air,intent:()=>({...intent}),selection:()=>selection,consumeIntent(){}},controlled:()=>x.unit,controlledAirModel:()=>({localPose:seq=>x.owner.packet(seq)}),controlSignature:v=>JSON.stringify(v),weaponSignature:null,guided:null,seekerSignature:null,cancelReleaseIntent(){},storeGroup:()=>null,send:p=>messages.push(p)});vm.runInContext(runtime.slice(from,to),c);c.transmit();assert.deepEqual(messages.map(x=>x.op),['air_weapon_control','air_input','air_pose']);assert.deepEqual(messages.map(x=>x.seq),[1,2,3]);assert.equal(messages[2].unit.battle,11);});
